              if(!bn){msg.style.color="#dc2626";msg.textContent="은행을 선택해주세요";return;}
              if(!bnum||bnum.length<10){msg.style.color="#dc2626";msg.textContent="올바른 계좌번호를 입력해주세요";return;}
              msg.style.color="#64748b";msg.textContent="확인 중...";
